#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int base, val;
    cin >> base >> val;

    vector<int> arr(110, 0);
    int length = 0;

    while (val > 0) {
        length++;
        arr[length] = val % base;
        val /= base;
    }

    for (int i = 1; i <= length; i++) {
        if (arr[i] > base / 2) {
            arr[i] = -(arr[i] - base);
            if (i + 1 <= length) {
                arr[i + 1]++;
            } else {
                arr.push_back(0);
                arr[length + 1] = 1;
                length++;
            }
        }
    }

    if (arr[length] == 1) {
        length++;
    }

    for (int i = 1; i <= length; i++) {
        if (arr[i] > 1) {
            cout << "NO\n";
            return 0;
        }
    }

    cout << "YES\n";
    return 0;
}
